TypeScript example:
import { RedwoodClient } from '@redwood/sdk'
const client = new RedwoodClient()
const schema = { name: 'price_check', parameters: { symbol: { type: 'string', required: true }, tags: { type: 'array', items: { type: 'string' }, required: false }}}
const args = { symbol: 'AAPL', tags: 'finance' } // string will be coerced to ['finance']
const { coerced, warnings } = client.validateAndCoerce(schema, args)
const stream = client.callFunction(schema, coerced, { stream: true })
for await (const chunk of stream) { console.log(chunk) }

Go example:
dispatcher := sdk.NewDispatcher(client)
schema := sdk.FunctionSchema{Name: "price_check", Parameters: map[string]sdk.Param{{"symbol": {Type: "string", Required: true}}}}
args := map[string]interface{}{"symbol": "AAPL", "limit": "5"}
coerced, warns := dispatcher.ValidateAndCoerce(schema, args)
stream, err := dispatcher.CallFunction(context.Background(), schema, coerced, sdk.CallOpts{Stream: true})
for chunk := range stream { fmt.Println(chunk) }
